constraint.description:
/* This property can only be associated with a spatial object that is an Aerodrome Node or Aerodrome Area. */
inv: networkRef.element.oclIsKindOf(AerodromeNode) or
networkRef.element.oclIsKindOf(AerodromeArea)

/* This property can only be associated with a spatial object that is an Air Route Link or Airspace Area. */
inv: networkRef.element.oclIsKindOf(AirRouteLink) or
networkRef.element.oclIsKindOf(AirspaceArea)

/* This property can only be associated with a spatial object that is an Air Route Link or Airspace Area. */
inv: networkRef.element.oclIsKindOf(AirRouteLink) or
networkRef.element.oclIsKindOf(AirspaceArea)

/* This property can only be associated with a spatial object that is part of a water transport network. */
inv: networkRef.element.oclIsKindOf(WaterwayLink) or
networkRef.element.oclIsKindOf(WaterwayNode)

/* This property can only be associated with a spatial object that is part of a water transport network. */
inv: networkRef.element.oclIsKindOf(WaterLinkSequence) or
networkRef.element.oclIsKindOf(WaterwayLink)

/* This property can only be associated with a spatial object of the type RoadServiceArea or RoadNode (when formOfRoadNode=roadServiceArea). */
inv: networkRef.element.oclIsKindOf(RoadServiceArea) or
(networkRef.element.oclIsKindOf(RoadNode) and networkRef.element. formOfRoadNode = FormOfRoadNodeValue::roadServiceArea)
